INSERT INTO classes (service_name, class_name, description) VALUES ('cardprocessor', 'ContactlessCVMLimitValidator', 'In certain Card-present environments, a Merchant may complete the Transaction without a CVM ("no CVM" as the CVM), such as - Contactless Transactions less than or equal to the CVM limit - Quick Payment Service(QPS)Transactions - Transactions at an unattended Point-of-Sale (POS) Terminal identified as Cardholder-activated Terminal (CAT) Level 2 or Level 3. Exceptions: - CVM must be obtained for any');
INSERT INTO classes (service_name, class_name, description) VALUES ('cardprocessor', 'ContactlessCumulativeLimitChecker', 'Checks the amount on the contactless transaction to see if it takes the customer over the cumulative limit. If this transaction would take the customer over the limit, the transaction is declined and the customer is expected to authorise with an online PIN. When this arrives, the cumulative limit for that card will be reset. If the transaction does not take the customer over the limit, the amount ');
