INSERT INTO classes (service_name, class_name, description) VALUES ('cardprocessor', 'NaturalReissueTransactionActivityJob', 'This daemon job is used to perform actions related to naturally expiring cards. It runs on the 20th of each month and will: - find all cards which are expiring in two months'' time. Of these cards, determine which ones have not performed a transaction in the last 6 months. For these unused cards, send an in-app message to the cardholders informing them that they need to perform a transaction in the');
INSERT INTO classes (service_name, class_name, description) VALUES ('cardprocessor', 'NaturalReissueUpdateAddressJob', 'This daemon job is used to perform actions related to naturally expiring cards. It runs on the 3rd of each month and will: - find all cards which are expiring in two months and have done transactions in the last 6 months. For these cards, send an in-app message to the cardholders asking them to ensure their address is up-to-date. (Runs after {@link NaturalReissueTransactionActivityJob}');
