INSERT INTO classes (service_name, class_name, description) VALUES ('cardprocessor', 'PresentmentReversalService', 'A presentment may be reversed by a following message with PDS 25 set accordingly. All other data elements in the reversal message remain unchanged from the original message. Ref: PDS 0025, 0026 subfields, IPM Clearing Formats, 25 Aug 2020 Transaction direction would be flipped to reverse the flow of previous message. Hence, new transaction and feed item will be created accordingly.');
