INSERT INTO classes (service_name, class_name, description) VALUES ('cardprocessor', 'RecurringPaymentIndicatorChecker', 'A recurring payment Transaction is a Transaction made pursuant to an agreement between a Cardholder and a Merchant, whereby the Cardholder authorizes the Merchant to store and use the Cardholder’s Mastercard Account or (where supported) Maestro Account data periodically and on an ongoing basis, with no specified end date. Use may occur periodically, such as on a monthly, quarterly, or annual basis');
INSERT INTO classes (service_name, class_name, description) VALUES ('cardprocessor', 'RecurringPaymentRuleHandler', 'An authorisation may not be challenged if it is a recurring payment whereby the original payment was challenged. We determine this by first looking up the initial authorisation using the dependent message ID (trace ID). The DS transaction ID from this initial transaction is then used to find the authentication details for the initial authorisation. This can then be checked to ensure it was fully a');
