INSERT INTO classes (service_name, class_name, description) VALUES ('cardprocessor', 'TokenisationActivationCodeNotificationHandler', 'Handles activation code notification messages. These are tokenisation messages where the first two characters of DE 124 (member-defined data) are "AC". An ACN is received as the result of a customer choosing SMS OTP as their authentication option. This contains a one-time code generated by MDES which the customer can then enter into their wallet app to complete the tokenisation process.');
INSERT INTO classes (service_name, class_name, description) VALUES ('cardprocessor', 'TokenisationAuthorisationHandler', 'Handles tokenisation authorisation messages. These are tokenisation messages where the first two characters of DE 124 (member-defined data) are "TA". There are three possible paths for authentication, commonly referred to as: 1) The green path - the tokenisation is allowed without further authentication 2) The yellow path - the tokenisation is allowed PENDING another authentication method success ');
