INSERT INTO classes (service_name, class_name, description) VALUES ('cardprocessor', 'TokenisationEventHandler', 'Handles tokenisation event messages. These are tokenisation messages where the first two characters of DE 124 (member-defined data) are "TV". These events are further sub-categorised into event types represented by ({@link com.starlingbank.card.connector.dataelement.memberdatade124.TokenisationEventIndicator}');
