INSERT INTO classes (service_name, class_name, description) VALUES ('mastercardfile', 'BulkAdvisementResponseHandler', 'Handles a Bulk File Advisement Response Message (202). This message contains data about a file present on the MIP. This handler will save any downloadable files for asynchronous processing and then sends a Data Acknowledgement Message (198) to the MIP in order to receive more data or a trailer message (298) indicating that all file details have been sent.');
