INSERT INTO classes (service_name, class_name, description) VALUES ('mastercardfile', 'ClearingContentLengthPrefixedReader', 'Consumes a stream of length tagged fields The format is as follows: Content length - 4 bytes in big-endian Content of length specified This repeats until we receive content length 0, at which point the message is padded out with padding bytes. Messages are often padded because they are sent over in blocks (see {@link ClearingChunkInputStream}), so need to fill the remainder of the block');
