INSERT INTO classes (service_name, class_name, description) VALUES ('tagnitecrest', 'ScheduleCardFileGenerationDaemonJob', 'This daemon job looks for any card file generation schedules which have not yet been performed. If found, an event is generated and stored in the database in a PENDING state. These are picked up by another daemon job to execute the file generation. This job also checks for any jobs which have timed out - they will be in an IN_PROGRESS state and started some pre-configured time in the past which is');
